hooks.command:
for py in python3 python; do "$py" -I -S -c 'import json' </dev/null >/dev/null 2>&1 && break; py=; done; [ -n "$py" ] || { echo 'BLOCKED: this guard cannot read the tool call -- no working python3 or python on PATH (see INSTALL.md).' >&2; exit 2; }; PYTHONIOENCODING=utf-8 "$py" -I -S -c 'import json,re,sys
def no(why):
    sys.stderr.write("BLOCKED: the PowerShell tool runs only the read-only commands .claude/settings.json allows it, written plainly (git status, diff and log; git branch listings; gh issue, pr and label listings and views; Get-ChildItem; Test-Path) -- "+why+". Run anything else through the Bash tool, which the Bash guard reads (permission-matrix.md S5).\n");sys.exit(2)
try:
    d=json.load(sys.stdin)
except Exception:
    d=None
if not isinstance(d,dict):
    sys.stderr.write("BLOCKED: this guard cannot read the tool call -- the payload is not a JSON object.\n");sys.exit(2)
t=d.get("tool_input")
t=t if isinstance(t,dict) else {}
if "command" not in t:
    sys.stderr.write("BLOCKED: this guard cannot read the tool call -- a PowerShell call with no command.\n");sys.exit(2)
c=str(t.get("command","")).strip()
if not c:
    sys.exit(0)
if not re.fullmatch(r"[A-Za-z0-9 _./:=+*%#~\\-]+",c) or "\\\\" in c or "//" in c:
    no("a quote, bracket, sigil, separator, network path or non-ASCII character is evaluated by PowerShell")
if re.search(r"(^|\s)[A-Za-z][A-Za-z0-9]+:",c):
    no("a PowerShell drive such as Env: or HKLM: is not a file path")
w=c.split()
o=[a.split("=")[0].lower() for a in w[2:] if a.startswith("-")]
def abbrev(a,full):
    return len(a)>=4 and full.startswith(a)
if w[:2] in (["git","status"],["git","diff"],["git","log"]):
    if any(abbrev(a,f) for a in o for f in ("--output","--ext-diff","--textconv")):
        no("this option writes a file or runs a configured program")
    sys.exit(0)
if w[:2]==["git","branch"]:
    keep={"-a","-r","-v","-vv","-l","--all","--remotes","--verbose","--list","--show-current","--merged","--no-merged","--contains","--no-contains","--points-at","--column","--no-column","--sort"}
    if any(a not in keep for a in o):
        no("only the listing options of git branch")
    if any(not a.startswith("-") for a in w[2:]) and not keep.intersection(o)-{"-a","-r","-v","-vv","--all","--remotes","--verbose","--show-current","--column","--no-column","--sort"}:
        no("a git branch with a name and no listing option creates a branch")
    sys.exit(0)
if w[:3] in (["gh","issue","list"],["gh","issue","view"],["gh","pr","list"],["gh","pr","view"],["gh","label","list"]):
    sys.exit(0)
if w[0].lower() in ("get-childitem","test-path"):
    sys.exit(0)
no("not one of them")
'; rc=$?; [ "$rc" -eq 0 ] || exit 2
